export type User = {
  id: string
  name: string
  notificationsEnabled: boolean
}

// In-memory stand-in for a database. Shared module state persists across
// requests within a single server process, so toggles are visible on refresh.
const user: User = {
  id: 'u_1',
  name: 'Ada Lovelace',
  notificationsEnabled: true,
}

export async function getUser(): Promise<User> {
  return { ...user }
}

export async function setNotificationsEnabled(enabled: boolean): Promise<void> {
  user.notificationsEnabled = enabled
}

