'use server'

import { revalidatePath } from 'next/cache'
import { getUser, setNotificationsEnabled } from '@/lib/user'

export async function toggleNotifications() {
  const user = await getUser()
  await setNotificationsEnabled(!user.notificationsEnabled)

  // Refresh the current page so it re-renders with the updated preference.
  // This revalidates the route's cached data/RSC payload without redirecting.
  revalidatePath('/')
}

