'use client'

import { useFormStatus } from 'react-dom'

export function SubmitButton({ enabled }: { enabled: boolean }) {
  const { pending } = useFormStatus()

  return (
    <button type="submit" disabled={pending}>
      {pending ? 'Saving…' : enabled ? 'Turn off' : 'Turn on'}
    </button>
  )
}

